export interface ProfileSeedBundle {
  version: 'legacy-profile-bundle-v1';
  tables: Record<ProfileSeedTableName, Array<Record<string, unknown>>>;
}

function quoteIdentifier(value: string): string {
  return `"${value.replaceAll('"', '""')}"`;
}

export function decodeProfileSeed(): ProfileSeedBundle {
  const canonicalJson = gunzipSync(Buffer.from(PROFILE_SEED_GZIP_BASE64, 'base64')).toString(
    'utf8',
  );
  const checksum = createHash('sha256').update(canonicalJson).digest('hex');
  if (checksum !== PROFILE_SEED_SHA256) throw new Error('Profile seed checksum mismatch.');
  return JSON.parse(canonicalJson) as ProfileSeedBundle;
}

export function buildTableUpsertSql(table: ProfileSeedTable): string {
  const columns = table.columns.map(quoteIdentifier).join(', ');
  const conflicts = table.conflictColumns.map(quoteIdentifier).join(', ');
  return `INSERT INTO ${quoteIdentifier(table.name)} (${columns})
SELECT ${columns}
FROM jsonb_populate_recordset(NULL::${quoteIdentifier(table.name)}, $1::jsonb)
ON CONFLICT (${conflicts}) DO NOTHING`;
}

export async function seedProfileBundle(prisma = new PrismaClient()): Promise<void> {
  const ownsClient = arguments.length === 0;
  const bundle = decodeProfileSeed();
  try {
    await prisma.$transaction(
      async (transaction) => {
        await transaction.$executeRawUnsafe(
          `SELECT set_config('startflow.profile_seed_mode', 'on', true)`,
        );
        for (const table of PROFILE_SEED_TABLES) {
          const rows =
            table.name === 'users'
              ? buildOperationalUserSeedRows(bundle.tables.users)
              : bundle.tables[table.name];
          if (rows.length === 0) continue;
          await transaction.$executeRawUnsafe(buildTableUpsertSql(table), JSON.stringify(rows));
          if (table.sequence) {
            const quotedTable = quoteIdentifier(table.name);
            await transaction.$executeRawUnsafe(
              `SELECT setval(
                 pg_get_serial_sequence('public.${table.name}', 'id'),
                 GREATEST(COALESCE((SELECT MAX(id) FROM ${quotedTable}), 1), 1),
                 true
               )`,
            );
          }
        }
        await transaction.$executeRawUnsafe(
          `INSERT INTO profile_seed_manifest(version, checksum_sha256, table_counts, applied_at)
           VALUES($1, $2, $3::jsonb, now())
           ON CONFLICT (version) DO UPDATE
           SET checksum_sha256 = EXCLUDED.checksum_sha256,
               table_counts = EXCLUDED.table_counts,
               applied_at = now()`,
          bundle.version,
          PROFILE_SEED_SHA256,
          JSON.stringify(PROFILE_SEED_COUNTS),
        );
      },
      { maxWait: 30_000, timeout: 180_000 },
    );

    process.stdout.write(
      `Profile seed ready: ${bundle.version} ${PROFILE_SEED_SHA256} ${JSON.stringify(PROFILE_SEED_COUNTS)}\n`,
    );
  } finally {
    if (ownsClient) await prisma.$disconnect();
  }
}

if (require.main === module) {
  void seedProfileBundle().catch(() => {
    process.stderr.write('Profile seed failed; credential and row details were suppressed.\n');
    process.exitCode = 1;
  });
}
